SELECT ident.*, COALESCE(al.canonical_counterparty_id, own.id) AS effective_cp FROM ( SELECT t.*, CASE WHEN t.attributed_name IS NOT NULL THEN 'name' WHEN t.creditor_id IS NOT NULL THEN 'creditor_id' WHEN t.counterparty_iban IS NOT NULL THEN 'iban' WHEN t.counterparty_name IS NOT NULL THEN 'name' END AS identity_type, CASE WHEN t.attributed_name IS NOT NULL THEN upper(trim(regexp_replace(normalize(t.attributed_name, NFC), '\s+', ' ', 'g'))) WHEN t.creditor_id IS NOT NULL THEN t.creditor_id WHEN t.counterparty_iban IS NOT NULL THEN t.counterparty_iban WHEN t.counterparty_name IS NOT NULL THEN upper(trim(regexp_replace(normalize(t.counterparty_name, NFC), '\s+', ' ', 'g'))) END AS identity_value FROM transactions t WHERE NOT EXISTS (SELECT 1 FROM transactions c WHERE c.split_parent_content_hash = t.content_hash AND c.split_parent_occurrence_index = t.occurrence_index) ) ident LEFT JOIN counterparty_alias al ON al.identity_type = ident.identity_type AND al.identity_value = ident.identity_value LEFT JOIN counterparties own ON own.identity_type = ident.identity_type AND own.identity_value = ident.identity_value
